inline int future_wait(void *self, int milliseconds) {
	int out = 0;
	hxn_buf err = HXN_BUF_EMPTY;
	hxn_status status;
	{
		hxn::Blocking zone;
		status = hxn_gpu_metal_future_wait((hxn_handle *)self, milliseconds, &out, &err);
	}
	hxn::check(status, err);
	return out;
}

